INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400001, now(), now(), 'seed', '<h2>كيف تقيس</h2><p>قِس فوق ملابس داخلية خفيفة، والشريط ملاصق للجسم دون شدّ. المقاسات المذكورة هي مقاسات الجسم لا مقاسات القطعة.</p><h3>النساء</h3><table><tr><th>المقاس</th><th>الصدر</th><th>الخصر</th><th>الأرداف</th></tr><tr><td>S</td><td>84 سم</td><td>66 سم</td><td>92 سم</td></tr><tr><td>M</td><td>90 سم</td><td>72 سم</td><td>98 سم</td></tr><tr><td>L</td><td>96 سم</td><td>78 سم</td><td>104 سم</td></tr><tr><td>XL</td><td>104 سم</td><td>86 سم</td><td>112 سم</td></tr></table><h3>الرجال</h3><table><tr><th>المقاس</th><th>الصدر</th><th>الخصر</th></tr><tr><td>S</td><td>94 سم</td><td>80 سم</td></tr><tr><td>M</td><td>100 سم</td><td>86 سم</td></tr><tr><td>L</td><td>108 سم</td><td>94 سم</td></tr><tr><td>XL</td><td>116 سم</td><td>102 سم</td></tr></table><h3>بين مقاسين؟</h3><p>اختر الأكبر في القطع المنسوجة، والأصغر في القطع القطنية القابلة للتمدد. كل صفحة منتج تذكر إن كان القَصّ ضيقًا أو واسعًا.</p>', 'دليل المقاسات', 'دليل المقاسات', 'جداول مقاسات الرجال والنساء والأطفال بالسنتيمتر، مع طريقة القياس الصحيحة.', 'مقاسات, دليل المقاسات, قياس', 'دليل المقاسات | Riyadh Fashion Hub', 'size-guide-ar', 'ar', -40001, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400002, now(), now(), 'seed', '<h2>How to measure</h2><p>Measure over light underwear, tape flat against the body and not pulled tight. The figures below are body measurements, not garment measurements.</p><h3>Women</h3><table><tr><th>Size</th><th>Bust</th><th>Waist</th><th>Hips</th></tr><tr><td>S</td><td>84 cm</td><td>66 cm</td><td>92 cm</td></tr><tr><td>M</td><td>90 cm</td><td>72 cm</td><td>98 cm</td></tr><tr><td>L</td><td>96 cm</td><td>78 cm</td><td>104 cm</td></tr><tr><td>XL</td><td>104 cm</td><td>86 cm</td><td>112 cm</td></tr></table><h3>Men</h3><table><tr><th>Size</th><th>Chest</th><th>Waist</th></tr><tr><td>S</td><td>94 cm</td><td>80 cm</td></tr><tr><td>M</td><td>100 cm</td><td>86 cm</td></tr><tr><td>L</td><td>108 cm</td><td>94 cm</td></tr><tr><td>XL</td><td>116 cm</td><td>102 cm</td></tr></table><h3>Between two sizes?</h3><p>Size up in woven pieces, down in stretch cotton. Every product page states whether the cut runs slim or relaxed.</p>', 'Size guide', 'Size guide', 'Women''s, men''s and kids'' size charts in centimetres, and how to measure properly.', 'sizing, size guide, measurements', 'Size guide | Riyadh Fashion Hub', 'size-guide', 'en', -40001, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

-- page: fabric-and-care (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-40002, now(), now(), 'seed', 'fabric-and-care', 'PAGE', 11, true, '65f023632bc46470c104b76f', 'PUBLISHED', null, null, 1, 'seed', 'seed', null, false, null, null, false, null, null, null, null, null)
on conflict (content_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400003, now(), now(), 'seed', '<h2>من أين تأتي أقمشتنا</h2><ul><li>القطن المُمشَّط من مصر وتركيا، بوزن 180 غرامًا للمتر فأعلى</li><li>الكتان من البرتغال، مغسول مسبقًا لتقليل الانكماش</li><li>الفيسكوز من لُبّ خشب معتمد من مجلس رعاية الغابات</li></ul><h2>العناية في مناخ الرياض</h2><p>الحرارة والغبار أقسى على النسيج من الغسيل نفسه.</p><ul><li>اغسل بماء بارد؛ الماء الساخن يثبّت العرق والغبار داخل الألياف</li><li>جفّف في الظل — الشمس المباشرة تُبهت الألوان الداكنة خلال أسابيع</li><li>اقلب القطع المطبوعة قبل الغسل والكي</li><li>الكتان يُكوى وهو رطب قليلًا، وإلا لن يستقيم</li></ul><h2>الوبر</h2><p>الوبر ليس عيبًا في القطن، بل ألياف قصيرة تتحرر مع الاستخدام. مشط النسيج يزيله دون إتلاف القطعة.</p>', 'الأقمشة والعناية', 'الأقمشة والعناية', 'من أين تأتي أقمشتنا، وكيف تعتني بها لتدوم مواسم لا موسمًا واحدًا.', 'أقمشة, عناية, غسيل', 'الأقمشة والعناية | Riyadh Fashion Hub', 'fabric-and-care-ar', 'ar', -40002, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400004, now(), now(), 'seed', '<h2>Where our fabric comes from</h2><ul><li>Combed cotton from Egypt and Türkiye, 180 gsm and up</li><li>Linen from Portugal, pre-washed to limit shrinkage</li><li>Viscose from FSC-certified wood pulp</li></ul><h2>Care in the Riyadh climate</h2><p>Heat and dust are harder on cloth than washing is.</p><ul><li>Wash cold; hot water sets perspiration and dust into the fibre</li><li>Dry in shade — direct sun fades dark dyes within weeks</li><li>Turn printed pieces inside out to wash and to iron</li><li>Iron linen slightly damp, or it will not sit flat</li></ul><h2>Pilling</h2><p>Pilling is not a fault in cotton: it is short fibres working loose. A fabric comb removes it without damaging the garment.</p>', 'Fabric & care', 'Fabric & care', 'Where our fabrics come from, and how to look after them so they last seasons rather than one summer.', 'fabric, care, washing', 'Fabric & care | Riyadh Fashion Hub', 'fabric-and-care', 'en', -40002, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

-- page: careers (PUBLISHED)
INSERT INTO content.content (content_id, date_created, date_modified, updt_id, code, content_type, sort_order, visible, store_merchant_id, status, publish_at, unpublish_at, version, created_by, updated_by, parent_id, noindex, canonical_url, og_media_id, show_in_footer, placement, starts_at, ends_at, policy_type, meta)
VALUES (-40003, now(), now(), 'seed', 'careers', 'PAGE', 12, true, '65f023632bc46470c104b76f', 'PUBLISHED', null, null, 1, 'seed', 'seed', null, false, null, null, true, null, null, null, null, null)
