INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400005, now(), now(), 'seed', '<h2>العمل معنا</h2><p>نحن اثنان وأربعون شخصًا بين معرض العليا ومستودع الخرج وفريق تصميم صغير.</p><h3>الشواغر الحالية</h3><ul><li>مستشار مبيعات — دوام كامل، العليا</li><li>مصمم أنماط — دوام كامل، الرياض</li><li>أخصائي تجارة إلكترونية — دوام كامل، عن بُعد داخل المملكة</li></ul><p>أرسل سيرتك إلى <a href="mailto:careers@riyadhfashionhub.sa">careers@riyadhfashionhub.sa</a> مع سطرين عن سبب اهتمامك بهذا المجال تحديدًا.</p>', 'الوظائف', 'الوظائف', 'وظائف شاغرة في المعرض والمستودع وفريق التصميم في الرياض.', 'وظائف, توظيف, الرياض', 'الوظائف | Riyadh Fashion Hub', 'careers-ar', 'ar', -40003, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400006, now(), now(), 'seed', '<h2>Working with us</h2><p>There are forty-two of us, across the Olaya store, the Al-Kharj warehouse and a small design team.</p><h3>Open roles</h3><ul><li>Sales advisor — full time, Olaya</li><li>Pattern designer — full time, Riyadh</li><li>E-commerce specialist — full time, remote within the Kingdom</li></ul><p>Send a CV to <a href="mailto:careers@riyadhfashionhub.sa">careers@riyadhfashionhub.sa</a> with two lines on why this particular field.</p>', 'Careers', 'Careers', 'Open roles across the Olaya store, the Al-Kharj warehouse and the design team.', 'jobs, hiring, riyadh', 'Careers | Riyadh Fashion Hub', 'careers', 'en', -40003, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

