INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400007, now(), now(), 'seed', '<h2>معارضنا</h2><p>هذه الصفحة تابعة لصفحة « موقعنا »، وتستخدم للتحقق من مسار التنقل: الرئيسية › موقعنا › معارضنا.</p><ul><li><strong>العليا، الرياض</strong> — المعرض الرئيسي، خدمة التعديل مجانًا — يوميًا 10ص إلى 11م</li><li><strong>الرياض بارك</strong> — مجموعة مختارة — يوميًا 10ص إلى 12م</li><li><strong>جدة، حي الروضة</strong> — يوميًا 4م إلى 12م</li></ul><h3>خدمة التعديل</h3><p>تقصير البناطيل وتضييق الأكتاف مجانًا على أي قطعة تُشترى من المعرض، والتسليم خلال ثلاثة أيام.</p>', 'معارضنا', 'معارضنا', 'ثلاثة معارض في الرياض وجدة، بمواعيدها وخدماتها.', 'معارض, فروع, الرياض, جدة', 'معارضنا | Riyadh Fashion Hub', 'our-stores-ar', 'ar', -40004, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400008, now(), now(), 'seed', '<h2>Our stores</h2><p>This page sits under “Location”, which makes it the breadcrumb check: it should read Home › Location › Our stores.</p><ul><li><strong>Olaya, Riyadh</strong> — flagship, free alterations — daily 10am–11pm</li><li><strong>Riyadh Park</strong> — selected range — daily 10am–midnight</li><li><strong>Al-Rawdah, Jeddah</strong> — daily 4pm–midnight</li></ul><h3>Alterations</h3><p>Hems and shoulder taper are free on anything bought in store, ready within three days.</p>', 'Our stores', 'Our stores', 'Three stores across Riyadh and Jeddah, with hours and in-store services.', 'stores, locations, riyadh, jeddah', 'Our stores | Riyadh Fashion Hub', 'our-stores', 'en', -40004, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

