INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400009, now(), now(), 'seed', '<h2>هدية لا تحتاج مقاسًا</h2><p>بطاقاتنا من 100 إلى 5000 ريال، رقمية تصل خلال دقائق، أو مطبوعة داخل ظرف قماشي يُرسل مجانًا داخل المملكة.</p><p>صالحة لسنتين، تُستخدم أونلاين وفي المعارض، والرصيد المتبقي يبقى على البطاقة.</p><p>تحمل هذه الصفحة رابطًا قانونيًا وصورة Open Graph للتحقق من بيانات الـ SEO في المتجر.</p>', 'بطاقات الهدايا', 'بطاقات الهدايا', 'بطاقات هدايا من 100 إلى 5000 ريال، صالحة سنتين أونلاين وفي المعارض.', 'بطاقة هدية, قسيمة شراء', 'بطاقات الهدايا | Riyadh Fashion Hub', 'gift-cards-ar', 'ar', -40005, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400010, now(), now(), 'seed', '<h2>A gift that needs no size</h2><p>Cards run from SAR 100 to SAR 5,000 — digital and delivered in minutes, or printed and posted free inside the Kingdom in a cloth envelope.</p><p>They are valid for two years, usable online and in store, and any remaining balance stays on the card.</p><p>This page carries a canonical URL and an Open Graph image, which makes it the check on the storefront''s SEO rendering.</p>', 'Gift cards', 'Gift cards', 'Gift cards from SAR 100 to SAR 5,000, valid two years online and in store.', 'gift card, voucher', 'Gift cards | Riyadh Fashion Hub', 'gift-cards', 'en', -40005, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

