INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400011, now(), now(), 'seed', '<h2>ما نقيسه</h2><p>هذه الصفحة مُعلَّمة بـ <code>noindex</code>: يجب أن تظهر في المتجر وتختفي من خريطة الموقع. هذا هو اختبار العلامة.</p><ul><li>التغليف ورقي بالكامل منذ 2025، بلا بلاستيك</li><li>94% من المرتجعات تعود للبيع بعد الفحص والكي</li><li>خدمة التعديل المجانية تطيل عمر القطعة، وهي أرخص إجراء بيئي متاح لنا</li></ul>', 'الاستدامة', 'الاستدامة', 'التغليف والمرتجعات وعمر القطعة — صفحة مستبعدة عمدًا من الفهرسة.', 'استدامة, تغليف, مرتجعات', 'الاستدامة | Riyadh Fashion Hub', 'sustainability-ar', 'ar', -40006, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400012, now(), now(), 'seed', '<h2>What we measure</h2><p>This page is flagged <code>noindex</code>: it should render in the storefront but stay out of the sitemap. That is the check on the SEO flag.</p><ul><li>Packaging has been all-paper since 2025, with no plastic</li><li>94% of returns go back on sale after inspection and pressing</li><li>Free alterations extend garment life, which is the cheapest environmental measure available to us</li></ul>', 'Sustainability', 'Sustainability', 'Packaging, returns and garment lifespan — a page deliberately kept out of the index.', 'sustainability, packaging, returns', 'Sustainability | Riyadh Fashion Hub', 'sustainability', 'en', -40006, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;

