VALUES (-400013, now(), now(), 'seed', '<h2>مجموعة رمضان</h2><p>هذه الصفحة بحالة <strong>SCHEDULED</strong> وتُنشر بعد ثلاثة أسابيع. يجب أن تظهر في لوحة التحكم وتعطي 404 في المتجر.</p>', 'مجموعة رمضان (مجدولة)', 'مجموعة رمضان (مجدولة)', 'صفحة مجدولة: يجب ألا تظهر في المتجر قبل موعد نشرها.', 'رمضان, مجموعة', 'مجموعة رمضان | Riyadh Fashion Hub', 'ramadan-collection-ar', 'ar', -40007, 'TRANSLATED', null, null, null, null)
