INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-400014, now(), now(), 'seed', '<h2>Ramadan collection</h2><p>This page is <strong>SCHEDULED</strong> to publish in three weeks. It should be visible in the console and 404 in the storefront.</p>', 'Ramadan collection (scheduled)', 'Ramadan collection (scheduled)', 'A scheduled page: it must not appear in the storefront before its publish date.', 'ramadan, collection', 'Ramadan collection | Riyadh Fashion Hub', 'ramadan-collection', 'en', -40007, 'TRANSLATED', null, null, null, null)
