VALUES (-400015, now(), now(), 'seed', '<h2>كتالوج 2024</h2><p>مؤرشف واستُبدل بكتالوج 2026. يجب أن يبقى غير مرئي في المتجر.</p>', 'كتالوج 2024 (مؤرشف)', 'كتالوج 2024 (مؤرشف)', null, null, null, 'lookbook-2024-ar', 'ar', -40008, 'TRANSLATED', null, null, null, null)
